<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,reactive,ref,watch} from 'vue';
import {createIsmClient,type components} from '@ism/api-client';
type View=components['schemas']['SupportRequest'];
const props=defineProps<{token:string;canRequest:boolean;canReview:boolean;tenant?:{id:string;name:string}}>();
const emit=defineEmits<{close:[]}>();const client=createIsmClient({getAccessToken:()=>props.token});
const labels:Record<View['status'],string>={DRAFT:'草稿',SUBMITTED:'待平台审批',PLATFORM_APPROVED:'平台已批准（未启用）',REJECTED:'已拒绝',CANCELLED:'已取消',EXPIRED:'已过期'};
const form=reactive({ticketNo:'',reason:'',profileCode:'SUPPLIER_BASIC_READ_V1' as const,durationMinutes:30});
const rows=ref<View[]>([]),selected=ref<View>(),review=ref(false),page=ref(0),total=ref(0),loading=ref(false),busy=ref(false),unknown=ref(false),error=ref(''),notice=ref(''),comment=ref(''),errorBox=ref<HTMLElement>();
type Action='submit'|'approve'|'reject'|'cancel';
const authorizationReasons:Record<string,string>={TENANT_UNAVAILABLE:'租户不可用',PLATFORM_REVIEW_REQUIRED:'缺少有效平台批准',EXPIRED:'已过期',OPERATOR_UNAVAILABLE:'平台申请人当前不具资格',POLICY_DISABLED:'租户策略已关闭',TENANT_REVIEW_REQUIRED:'等待本租户明确审批',APPROVED:'已批准',REJECTED:'租户已拒绝',REVOKED:'租户已撤回',ROLE_UNAVAILABLE:'角色或模块当前不可用',EMPTY_INTERSECTION:'当前权限交集为空',AUTHORIZATION_READY_SESSION_DISABLED:'授权依据已满足，仍不启用会话'};
const authorization=ref<components['schemas']['SupportAuthorization']>();
async function checkAuthorization(){if(fixed.value||!selected.value)return;busy.value=true;error.value='';authorization.value=undefined;try{const r=await client.GET('/console/support-requests/{id}/authorization',{params:{path:{id:selected.value.id}}});if(!mounted)return;if(r.error)error.value=r.error.error.message;else authorization.value=r.data.data;}catch{if(mounted)error.value='授权交集读取失败，请重新检查';}finally{if(mounted)busy.value=false;}}
const command=ref<Action>();const preparing=ref(false);
let mounted=true,epoch=0;let attempt:({kind:'create';body:components['schemas']['CreateSupportRequest'];tenantId:string}|{kind:Action;body:components['schemas']['ChangeSupportRequest'];id:string})&{key:string}|null=null;
const fixed=computed(()=>busy.value||unknown.value);watch(error,async value=>{if(value){await nextTick();errorBox.value?.focus();}});
async function load(next=0){if(fixed.value)return;const id=++epoch,token=props.token;loading.value=true;error.value='';rows.value=[];selected.value=undefined;authorization.value=undefined;command.value=undefined;try{const r=await client.GET('/console/support-requests',{params:{query:{review:review.value,page:next,size:10}}});if(!mounted||id!==epoch||token!==props.token)return;if(r.error){error.value=r.error.error.message;return;}rows.value=r.data.data.items;total.value=r.data.data.total;page.value=next;}catch{if(mounted&&id===epoch)error.value='支持申请读取失败，请重新读取';}finally{if(mounted&&id===epoch)loading.value=false;}}
async function detail(id:string){authorization.value=undefined;if(fixed.value||loading.value)return;busy.value=true;error.value='';const token=props.token;try{const r=await client.GET('/console/support-requests/{id}',{params:{path:{id}}});if(!mounted||token!==props.token)return;if(r.error){selected.value=undefined;authorization.value=undefined;error.value=r.error.error.message;return;}selected.value=r.data.data;command.value=undefined;comment.value='';}catch{if(mounted)error.value='申请详情读取失败，请重新读取';}finally{if(mounted&&token===props.token)busy.value=false;}}
function choose(action:Action){if(fixed.value)return;command.value=action;comment.value='';error.value='';}
async function create(){if(fixed.value)return;attempt={kind:'create',tenantId:props.tenant!.id,key:crypto.randomUUID(),body:{...form,ticketNo:form.ticketNo.trim(),reason:form.reason.trim()}};await send();}
async function decide(){if(fixed.value||!selected.value||!command.value||!comment.value.trim())return;attempt={kind:command.value,id:selected.value.id,key:crypto.randomUUID(),body:{version:selected.value.version,comment:comment.value.trim()}};await send();}
async function send(){if(!attempt||busy.value)return;authorization.value=undefined;const a=attempt,token=props.token,wasUnknown=unknown.value;busy.value=true;error.value='';notice.value='';try{const r=a.kind==='create'?await client.POST('/console/tenants/{tenantId}/support-requests',{params:{path:{tenantId:a.tenantId},header:{'Idempotency-Key':a.key}},body:a.body}):await client.POST(a.kind==='submit'?'/console/support-requests/{id}/submit':a.kind==='approve'?'/console/support-requests/{id}/approve':a.kind==='reject'?'/console/support-requests/{id}/reject':'/console/support-requests/{id}/cancel',{params:{path:{id:a.id},header:{'Idempotency-Key':a.key}},body:a.body});if(!mounted||token!==props.token)return;if(r.error){unknown.value=wasUnknown||r.response.status>=500;error.value=unknown.value?'操作结果尚未确认，请使用原请求重试；权限变化时联系管理员核对申请':r.error.error.message;if(!unknown.value){attempt=null;command.value=undefined;selected.value=undefined;authorization.value=undefined;}return;}if(!r.data?.data)throw Error('Unknown response');const result=r.data.data;attempt=null;unknown.value=false;selected.value=result;command.value=undefined;comment.value='';preparing.value=false;notice.value=`操作回执：${labels[result.status]}。回执不代表已获得租户访问权限，请重新读取核对当前状态。`;if(a.kind==='create'){form.ticketNo='';form.reason='';}try{const list=await client.GET('/console/support-requests',{params:{query:{review:review.value,page:0,size:10}}});if(!mounted||token!==props.token)return;if(list.error)notice.value+=' 列表读取失败，请重新读取。';else{rows.value=list.data.data.items;total.value=list.data.data.total;page.value=0;}const latest=await client.GET('/console/support-requests/{id}',{params:{path:{id:result.id}}});if(!mounted||token!==props.token)return;if(latest.data)selected.value=latest.data.data;else notice.value+=' 当前详情未确认，请重新读取。';}catch{if(mounted&&token===props.token)notice.value+=' 操作回执已收到，后续读取失败，请重新读取；勿重复操作。';}}catch{if(mounted&&token===props.token){unknown.value=true;error.value='操作结果尚未确认，请使用原请求重试，勿重复提交';}}finally{if(mounted&&token===props.token)busy.value=false;}}
onMounted(()=>{void load();});onBeforeUnmount(()=>{mounted=false;epoch++;attempt=null;});
</script>
<template><section class="panel support-requests" aria-label="支持访问申请"><h2>支持访问申请{{tenant?` · ${tenant.name}`:''}}</h2><p>当前提供申请、独立平台审批及租户授权交集检查。平台批准不代表租户授权或会话启用；这里不会提供进入租户、搜索、下载或写业务数据的能力。</p><p v-if="error" ref="errorBox" role="alert" tabindex="-1">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><div class="actions"><button type="button" :disabled="fixed" @click="emit('close')">关闭支持申请</button><button type="button" :disabled="fixed||loading" @click="load(0)">重新读取申请</button><button v-if="tenant&&canRequest" type="button" :disabled="fixed||loading" @click="preparing=!preparing;selected=undefined;command=undefined">新建支持申请</button><label v-if="canReview" class="check"><input v-model="review" type="checkbox" :disabled="fixed||loading" @change="load(0)"/>查看已提交审批队列</label></div>
<form v-if="preparing&&tenant&&canRequest" @submit.prevent="create"><fieldset :disabled="fixed"><label>工单编号<input v-model="form.ticketNo" required maxlength="100"/></label><label>支持原因<textarea v-model="form.reason" required maxlength="1000" rows="3"/></label><label>申请有效分钟数<input v-model.number="form.durationMinutes" required type="number" min="5" max="60"/></label><p>固定提案：目标租户供应商基础字段只读（ID、编码、名称、类型、状态），不含联系人、证件、附件或写入；有效期自创建时数据库 UTC 开始计算。必须由其他平台审批人审核。</p></fieldset><button v-if="!unknown" type="submit" :disabled="busy">保存支持申请草稿</button></form>
<p v-if="loading" role="status">正在读取支持申请…</p><div v-else class="scroll"><table><thead><tr><th>申请编号 / 工单</th><th>目标租户</th><th>申请人</th><th>状态</th><th>申请失效时间（UTC）</th><th>操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.bizNo}} / {{r.ticketNo}}</td><td>{{r.tenantName}}（{{r.tenantCode}}）</td><td>{{r.operatorName}}</td><td>{{labels[r.status]}}</td><td>{{r.requestedExpireAt}}</td><td><button type="button" :disabled="fixed" @click="detail(r.id)">查看支持申请</button></td></tr><tr v-if="!rows.length"><td colspan="6">当前未加载到支持申请，请核对队列或重新读取。</td></tr></tbody></table></div><div class="actions"><button type="button" :disabled="fixed||loading||page===0" @click="load(page-1)">上一页申请</button><span>第 {{page+1}} 页</span><button type="button" :disabled="fixed||loading||page>=10000||(page+1)*10>=total" @click="load(page+1)">下一页申请</button></div>
<section v-if="selected" aria-label="支持申请详情"><h3>{{selected.bizNo}} · {{labels[selected.status]}}</h3><p>工单：{{selected.ticketNo}}；申请人：{{selected.operatorName}}；目标：{{selected.tenantName}}（{{selected.tenantCode}}）。</p><p>原因：{{selected.reason}}</p><p>固定动作：{{selected.profile.actions.join('、')}}；字段：{{selected.profile.fields.join('、')}}；范围：目标租户。申请失效：{{selected.requestedExpireAt}} UTC。</p><p v-if="selected.status==='PLATFORM_APPROVED'">平台审批已完成，尚未启用支持会话，不能访问租户业务。</p><div class="actions"><button v-if="selected.canSubmit&&canRequest" type="button" :disabled="fixed" @click="choose('submit')">提交平台审批</button><button v-if="selected.canCancel&&canRequest" type="button" :disabled="fixed" @click="choose('cancel')">取消支持申请</button><button v-if="selected.canReview&&canReview" type="button" :disabled="fixed" @click="choose('approve')">批准平台申请</button><button v-if="selected.canReview&&canReview" type="button" :disabled="fixed" @click="choose('reject')">拒绝平台申请</button><button type="button" :disabled="fixed" @click="detail(selected.id)">重新读取详情</button></div>
<form v-if="command" @submit.prevent="decide"><h4>{{command==='approve'?'确认平台批准（不会启用会话）':command==='reject'?'确认拒绝':command==='submit'?'确认提交平台审批':'确认取消支持申请'}}</h4><label>处理意见<textarea v-model="comment" required maxlength="1000" rows="3" :disabled="fixed"/></label><button v-if="!unknown" type="submit" :disabled="busy">确认处理支持申请</button></form><button type="button" :disabled="fixed" @click="checkAuthorization">检查租户授权交集</button><p v-if="authorization" role="status">{{authorization.authorizationReady?'授权交集已满足，支持会话仍未启用':'授权交集未满足'}} · {{authorizationReasons[authorization.reason]??authorization.reason}}<span v-if="authorization.authorizationReady">；字段：{{authorization.scope.fields.join('、')}}；范围：{{authorization.scope.tenantAll?'租户全部':authorization.scope.organizations.join('、')}}；截止：{{authorization.expiresAt}} UTC</span></p><h4>申请与审批轨迹</h4><ol><li v-for="event in selected.events" :key="event.id">{{event.occurredAt}} UTC · {{event.actorName}} · {{event.action}} · {{event.comment}}</li></ol></section><button v-if="unknown" type="button" :disabled="busy" @click="send">使用原请求重试支持操作</button></section></template>
<style scoped>.support-requests{margin-top:20px;}.support-requests p,.support-requests li{line-height:1.6;overflow-wrap:anywhere;}.actions{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:12px 0;}button{width:auto;min-height:44px;padding:0 14px;margin:0;}.scroll{max-width:100%;overflow-x:auto;}.scroll table{min-width:820px;}fieldset{padding:0;border:0;min-width:0;}input:not([type=checkbox]),textarea{width:100%;min-width:0;box-sizing:border-box;font:inherit;}textarea{border:1px solid #c8d2da;border-radius:5px;padding:10px;}.check{display:flex;align-items:center;gap:8px;margin:0;}.check input{width:20px;height:20px;}form{margin:16px 0;max-width:760px;}[role=alert]{color:#a52828;}</style>
